@Command([EditDocument];"1");
@Command([FileSave]);

@If (Company= ""; @Return(@Do(@Command([EditGotoField];"Company") ;@Prompt([Ok];"Missing Value"; "Please select Company before proceeding!")));"");
@If (Name= ""; @Return(@Do(@Command([EditGotoField];"Name") ;@Prompt([Ok];"Missing Value"; "Please enter your Name before proceeding!")));"");
@If (Date= ""; @Return(@Do(@Command([EditGotoField];"Date") ;@Prompt([Ok];"Missing Value"; "Please select Date before proceeding!")));"");
@If (Dept= ""; @Return(@Do(@Command([EditGotoField];"Dept") ;@Prompt([Ok];"Missing Value"; "Please select Department before proceeding!")));"");

@Command([FileSave]);

FIELD CA						:="Submitted";

@Command([FileSave]);

@MailSend(PIC;DocAuthor:CC:DefCC:HRHOD;"Qayyim/PanCen/PHB"; @DbTitle + " : New Complaint Submitted - "+ NotNum;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);

